function lastStoneWeight(stones) {
  const pile = stones.slice();
  while (pile.length > 1) {
    pile.sort((a, b) => a - b);
    const y = pile.pop();
    const x = pile.pop();
    if (y !== x) pile.push(y - x);
  }
  return pile.length ? pile[0] : 0;
}
